SELECT DATE_TRUNC('MONTH', opened_date) AS activity_month, COUNT_IF(account_type = 'CREDIT') AS credit_events, AVG(balance) FILTER (WHERE status = 'OPEN') AS open_avg_balance, ROUND(SUM(balance) / NULLIF(COUNT(CASE WHEN status = 'FROZEN' THEN 1 END), 0), 2) AS balance_per_frozen, ROUND(SUM(balance) / NULLIF(COUNT(CASE WHEN status = 'CLOSED' THEN 1 END), 0), 2) AS balance_per_closed, PERCENTILE_APPROX(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, COUNT(*) FILTER (WHERE account_type = 'LOAN') AS loan_rows FROM accounts GROUP BY DATE_TRUNC('MONTH', opened_date)
